-- Lab ICO order lines. {START} = July 1 two fiscal years back (yyyy-mm-dd). Keep in step with ORDER_SQL in src/page.html.
WITH l AS (SELECT "Order Number" SO, LEFT("Expense Dept",4) DEPT, TRIM("Ship To Site Region") GEO, TRIM(REPLACE("Ship To Party Name",CHR(9),' ')) SHIPTO, "Account" ACCT, COALESCE(NULLIF(NULLIF(NULLIF(TRIM("Project"),''),'0'),'00000'),'') PROJ, TO_CHAR("Order Date") OD, "Ordered Item" PN, "Line Status" LS, "Ordered Quantity" Q, COALESCE("Shipped Quantity",0) SQ, ROUND(COALESCE("Item Standard Cost",0)*"Ordered Quantity",2) C, TO_CHAR("Actual Ship Date") ASD, TO_CHAR("Schedule Ship Date") SSD, TO_CHAR("Receipt Date") RCD, IFF("Line Type" ILIKE '%RETURN%' OR "Ordered Quantity"<0,1,0) RET FROM EDNA.CONS_INSIGHTS_MART.EDNA_ORDER_MANAGEMENT_REPORT WHERE "Account" RLIKE '^[0-9]{5}$' AND "Line Status" <> 'CANCELED' AND LEFT("Expense Dept",4) IN ('7030','7110','7120','7130','7140') AND NOT (COALESCE("Source System Code",'')='ORACLE_EBS' AND "Actual Ship Date" IS NULL AND "Receipt Date" IS NULL)) SELECT * FROM l WHERE SO IN (SELECT SO FROM l GROUP BY SO HAVING MAX(COALESCE(ASD,RCD,SSD,OD)) >= '{START}' OR SUM(IFF(ASD IS NULL AND RCD IS NULL,1,0))>0) ORDER BY SO
